from rest_framework import viewsets, status
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import AllowAny, IsAuthenticated
from django.db import connection
import stripe

from .authentication import ApiKeyAuthentication
from .models import Order
from .serializers import OrderSerializer


class OrderViewSet(viewsets.ModelViewSet):
    queryset = Order.objects.all().select_related('customer')
    serializer_class = OrderSerializer
    authentication_classes = [ApiKeyAuthentication]
    permission_classes = [IsAuthenticated]

    def get_queryset(self):
        qs = super().get_queryset()
        return qs.filter(customer__api_key_id=self.request.auth.key_id)

    def perform_create(self, serializer):
        serializer.save(customer=self.request.user)


class HealthCheckView(APIView):
    authentication_classes = []
    permission_classes = [AllowAny]

    def get(self, request):
        with connection.cursor() as cur:
            cur.execute('SELECT 1')
        return Response({'status': 'ok'})


class StripeWebhookView(APIView):
    authentication_classes = []
    permission_classes = [AllowAny]

    def post(self, request):
        sig = request.META.get('HTTP_STRIPE_SIGNATURE', '')
        try:
            event = stripe.Webhook.construct_event(
                request.body, sig, settings_webhook_secret()
            )
        except (ValueError, stripe.error.SignatureVerificationError):
            return Response(status=status.HTTP_400_BAD_REQUEST)
        handle_event(event)
        return Response({'received': True})


def settings_webhook_secret():
    from django.conf import settings
    return settings.STRIPE_WEBHOOK_SECRET


def handle_event(event):
    pass

from rest_framework.authentication import BaseAuthentication
from rest_framework.exceptions import AuthenticationFailed

from .models import ApiKey


class ApiKeyAuthentication(BaseAuthentication):
    """Authenticate via 'Authorization: Api-Key <token>' header."""

    keyword = 'Api-Key'

    def authenticate(self, request):
        header = request.META.get('HTTP_AUTHORIZATION', '')
        parts = header.split()
        if not parts or parts[0] != self.keyword:
            return None
        if len(parts) != 2:
            raise AuthenticationFailed('Malformed Api-Key header.')
        try:
            key = ApiKey.objects.select_related('customer').get(
                token=parts[1], revoked=False
            )
        except ApiKey.DoesNotExist:
            raise AuthenticationFailed('Invalid API key.')
        return (key.customer, key)

    def authenticate_header(self, request):
        return self.keyword

from django.db import models


class Customer(models.Model):
    name = models.CharField(max_length=120)
    email = models.EmailField(unique=True)
    created_at = models.DateTimeField(auto_now_add=True)

    @property
    def is_authenticated(self):
        return True


class ApiKey(models.Model):
    customer = models.ForeignKey(Customer, on_delete=models.CASCADE, related_name='api_keys')
    token = models.CharField(max_length=64, unique=True, db_index=True)
    revoked = models.BooleanField(default=False)
    created_at = models.DateTimeField(auto_now_add=True)

    @property
    def key_id(self):
        return self.pk


class Order(models.Model):
    customer = models.ForeignKey(Customer, on_delete=models.CASCADE, related_name='api_key_orders')
    status = models.CharField(max_length=20, default='pending')
    total_cents = models.PositiveIntegerField()
    created_at = models.DateTimeField(auto_now_add=True)

