import pytest
from django.core.cache import caches
from rest_framework.test import APIClient

from orders.tests.factories import ApiKeyFactory


@pytest.fixture(autouse=True)
def clear_throttle():
    caches['throttle'].clear()
    yield
    caches['throttle'].clear()


def client_for(key):
    c = APIClient()
    c.credentials(HTTP_AUTHORIZATION='Api-Key ' + key.secret)
    return c


@pytest.mark.django_db
def test_read_limit_returns_429():
    c = client_for(ApiKeyFactory())
    for _ in range(100):
        assert c.get('/api/v1/orders/').status_code == 200
    assert c.get('/api/v1/orders/').status_code == 429


@pytest.mark.django_db
def test_write_limit_returns_429():
    c = client_for(ApiKeyFactory())
    for _ in range(20):
        assert c.post('/api/v1/orders/', {}, format='json').status_code != 429
    assert c.post('/api/v1/orders/', {}, format='json').status_code == 429


@pytest.mark.django_db
def test_retry_after_header_present():
    c = client_for(ApiKeyFactory())
    for _ in range(20):
        c.post('/api/v1/orders/', {}, format='json')
    r = c.post('/api/v1/orders/', {}, format='json')
    assert r.status_code == 429
    assert int(r['Retry-After']) > 0


@pytest.mark.django_db
def test_read_retry_after_header_present():
    c = client_for(ApiKeyFactory())
    for _ in range(100):
        c.get('/api/v1/orders/')
    r = c.get('/api/v1/orders/')
    assert int(r['Retry-After']) > 0


@pytest.mark.django_db
def test_keys_are_isolated():
    a, b = client_for(ApiKeyFactory()), client_for(ApiKeyFactory())
    for _ in range(100):
        a.get('/api/v1/orders/')
    assert a.get('/api/v1/orders/').status_code == 429
    assert b.get('/api/v1/orders/').status_code == 200


@pytest.mark.django_db
def test_ip_fallback_uses_first_forwarded_entry():
    c = APIClient()
    for _ in range(100):
        c.get('/api/v1/orders/', HTTP_X_FORWARDED_FOR='1.2.3.4, 10.0.0.1')
    assert c.get('/api/v1/orders/', HTTP_X_FORWARDED_FOR='1.2.3.4, 10.0.0.9').status_code == 429
    assert c.get('/api/v1/orders/', HTTP_X_FORWARDED_FOR='5.6.7.8, 10.0.0.1').status_code != 429


@pytest.mark.django_db
def test_health_exempt():
    c = APIClient()
    for _ in range(150):
        assert c.get('/api/v1/health/').status_code == 200


@pytest.mark.django_db
def test_stripe_webhook_exempt():
    c = APIClient()
    for _ in range(50):
        assert c.post('/api/v1/webhooks/stripe/', {}, format='json').status_code != 429


@pytest.mark.django_db
def test_read_and_write_scopes_independent():
    c = client_for(ApiKeyFactory())
    for _ in range(20):
        c.post('/api/v1/orders/', {}, format='json')
    assert c.get('/api/v1/orders/').status_code == 200


@pytest.mark.django_db
def test_patch_counts_as_write():
    c = client_for(ApiKeyFactory())
    for _ in range(20):
        c.patch('/api/v1/orders/1/', {}, format='json')
    assert c.patch('/api/v1/orders/1/', {}, format='json').status_code == 429


@pytest.mark.django_db
def test_delete_counts_as_write():
    c = client_for(ApiKeyFactory())
    for _ in range(20):
        c.delete('/api/v1/orders/1/')
    assert c.delete('/api/v1/orders/1/').status_code == 429

