import { useEffect, useRef, useState } from 'react';
import { checkEmail, CheckEmailError } from '../api/checkEmail';

export type ValidationState =
  | { status: 'idle' }
  | { status: 'checking' }
  | { status: 'valid' }
  | { status: 'invalid'; message: string };

const DEBOUNCE_MS = 400;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function useDebouncedValidation(email: string): ValidationState {
  const [state, setState] = useState<ValidationState>({ status: 'idle' });
  const controllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    controllerRef.current?.abort();

    if (email === '') {
      setState({ status: 'idle' });
      return;
    }
    if (!EMAIL_RE.test(email)) {
      setState({ status: 'invalid', message: 'Enter a valid email address' });
      return;
    }

    setState({ status: 'checking' });
    const timer = setTimeout(async () => {
      const controller = new AbortController();
      controllerRef.current = controller;
      try {
        await checkEmail(email, { signal: controller.signal });
        setState({ status: 'valid' });
      } catch (err) {
        if (controller.signal.aborted) return;
        if (err instanceof CheckEmailError && err.status === 409) {
          setState({ status: 'invalid', message: 'Email already registered' });
        } else {
          setState({ status: 'invalid', message: 'Could not verify email' });
        }
      }
    }, DEBOUNCE_MS);

    return () => {
      clearTimeout(timer);
      controllerRef.current?.abort();
    };
  }, [email]);

  return state;
}

export class CheckEmailError extends Error {
  constructor(message: string, public status: number) {
    super(message);
    this.name = 'CheckEmailError';
  }
}

export interface CheckEmailOptions {
  signal?: AbortSignal;
}

export async function checkEmail(
  email: string,
  { signal }: CheckEmailOptions = {}
): Promise<{ available: true }> {
  const res = await fetch('/api/check-email', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email }),
    signal,
  });

  if (res.status === 409) {
    throw new CheckEmailError('Email already registered', 409);
  }
  if (!res.ok) {
    throw new CheckEmailError(`Unexpected status ${res.status}`, res.status);
  }
  return res.json();
}

import { http, HttpResponse, delay } from 'msw';

// Default handlers used by every test unless overridden with server.use(...).
export const handlers = [
  http.post('/api/check-email', async ({ request }) => {
    const body = (await request.json()) as { email?: string };

    if (!body.email) {
      return HttpResponse.json({ error: 'Email required' }, { status: 400 });
    }

    // Simulates the real service's latency.
    await delay(250 + Math.random() * 250);

    if (body.email === 'taken@acme.test') {
      return HttpResponse.json(
        { error: 'Email already registered' },
        { status: 409 }
      );
    }
    return HttpResponse.json({ available: true });
  }),
];

