use std::process::ExitCode;

use clap::Parser;

use crate::cli::{Cli, Command, OutputFormat};
use crate::error::AppError;
use crate::report::Summary;

fn main() -> ExitCode {
    let cli = Cli::parse();
    match cli.command {
        Command::Check {
            file,
            format,
            max_errors,
        } => match run_check(&file, format, max_errors) {
            Ok(code) => ExitCode::from(code),
            Err(e) => {
                eprintln!("logscan: {e}");
                ExitCode::from(2)
            }
        },
    }
}

fn run_check(
    path: &std::path::Path,
    format: OutputFormat,
    max_errors: Option<usize>,
) -> Result<u8, AppError> {
    let _ = max_errors;
    let content = std::fs::read_to_string(path)?;
    let mut summary = Summary::default();

    for (idx, line) in content.lines().enumerate() {
        summary.total += 1;
        if line.trim().is_empty() {
            continue;
        }
        if let Err(e) = parser::parse_line(line, idx + 1) {
            summary.record(&e);
        }
    }

    match format {
        OutputFormat::Text => print!("{}", report::render_text(&summary)),
        OutputFormat::Json => print!("{}", report::render_json(&summary)),
    }

    Ok(if summary.invalid > 0 { 1 } else { 0 })
}

use std::path::PathBuf;

use clap::{Parser, Subcommand, ValueEnum};

#[derive(Parser, Debug)]
#[command(name = "logscan", version, about = "Validate structured application log files")]
pub struct Cli {
    #[command(subcommand)]
    pub command: Command,
}

#[derive(Subcommand, Debug)]
pub enum Command {
    /// Check a log file for malformed lines
    Check {
        /// Path to the log file
        file: PathBuf,

        /// Output format
        #[arg(long, value_enum, default_value_t = OutputFormat::Text)]
        format: OutputFormat,

        /// Stop after this many invalid lines
        #[arg(long)]
        max_errors: Option<usize>,
    },
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, ValueEnum)]
pub enum OutputFormat {
    Text,
    Json,
}

use chrono::DateTime;

use crate::error::ParseError;

#[derive(Debug, Clone, PartialEq)]
pub struct LogEntry {
    pub timestamp: String,
    pub level: Level,
    pub module: String,
    pub message: String,
    pub fields: Vec<(String, String)>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Level {
    Trace,
    Debug,
    Info,
    Warn,
    Error,
}

pub fn parse_line(line: &str, lineno: usize) -> Result<LogEntry, ParseError> {
    let _ = lineno;
    let (ts, rest) = split_timestamp(line)?;
    let rest = rest.trim_start();

    let close = rest.find(']').ok_or(ParseError::UnknownLevel(String::new()))?;
    if !rest.starts_with('[') {
        return Err(ParseError::UnknownLevel(String::new()));
    }
    let level = parse_level(&rest[1..close])?;
    let rest = rest[close + 1..].trim_start();

    let colon = rest.find(": ").ok_or(ParseError::BadModule)?;
    let module = &rest[..colon];
    if module.is_empty()
        || !module
            .split("::")
            .all(|seg| !seg.is_empty() && seg.chars().all(|c| c.is_ascii_alphanumeric() || c == '_'))
    {
        return Err(ParseError::BadModule);
    }
    let body = &rest[colon + 2..];
    let (message, fields) = parse_fields(body)?;

    Ok(LogEntry {
        timestamp: ts.to_string(),
        level,
        module: module.to_string(),
        message,
        fields,
    })
}

fn split_timestamp(line: &str) -> Result<(&str, &str), ParseError> {
    let end = line.find(' ').unwrap_or(line.len());
    let ts = &line[..end];
    let parsed = DateTime::parse_from_rfc3339(ts)
        .map_err(|_| ParseError::BadTimestamp { col: 0 })?;
    if !ts.ends_with('Z') || parsed.offset().local_minus_utc() != 0 {
        return Err(ParseError::BadTimestamp { col: ts.len().saturating_sub(1) });
    }
    Ok((ts, &line[end..]))
}

fn parse_level(s: &str) -> Result<Level, ParseError> {
    match s {
        "TRACE" => Ok(Level::Trace),
        "DEBUG" => Ok(Level::Debug),
        "INFO" => Ok(Level::Info),
        "WARN" => Ok(Level::Warn),
        "ERROR" => Ok(Level::Error),
        other => Err(ParseError::UnknownLevel(other.to_string())),
    }
}

fn parse_fields(body: &str) -> Result<(String, Vec<(String, String)>), ParseError> {
    let mut message_words = Vec::new();
    let mut fields = Vec::new();
    for tok in body.split_whitespace() {
        match tok.split_once('=') {
            Some((k, v)) if !k.is_empty() && !v.is_empty() => {
                fields.push((k.to_string(), v.to_string()))
            }
            Some((k, _)) => return Err(ParseError::MalformedField { key: k.to_string() }),
            None => message_words.push(tok),
        }
    }
    Ok((message_words.join(" "), fields))
}

use serde_json::json;

use crate::error::ParseError;

#[derive(Debug, Default)]
pub struct Summary {
    pub total: usize,
    pub invalid: usize,
    pub bad_timestamp: usize,
    pub unknown_level: usize,
    pub bad_module: usize,
    pub malformed_field: usize,
}

impl Summary {
    pub fn record(&mut self, e: &ParseError) {
        self.invalid += 1;
        match e {
            ParseError::BadTimestamp { .. } => self.bad_timestamp += 1,
            ParseError::UnknownLevel(_) => self.unknown_level += 1,
            ParseError::BadModule => self.bad_module += 1,
            ParseError::MalformedField { .. } => self.malformed_field += 1,
        }
    }
}

pub fn render_text(s: &Summary) -> String {
    let mut out = String::new();
    out.push_str(&format!("{} invalid / {} total\n", s.invalid, s.total));
    out.push_str(&format!("  bad timestamp:   {}\n", s.bad_timestamp));
    out.push_str(&format!("  unknown level:   {}\n", s.unknown_level));
    out.push_str(&format!("  bad module:      {}\n", s.bad_module));
    out.push_str(&format!("  malformed field: {}\n", s.malformed_field));
    out
}

pub fn render_json(s: &Summary) -> String {
    let v = json!({
        "total": s.total,
        "invalid": s.invalid,
        "counters": {
            "bad_timestamp": s.bad_timestamp,
            "unknown_level": s.unknown_level,
            "bad_module": s.bad_module,
            "malformed_field": s.malformed_field,
        }
    });
    serde_json::to_string_pretty(&v).unwrap() + "\n"
}

use assert_cmd::Command;
