static LINE_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(
        r"^(?P<ts>\S+)\s\[(?P<level>[A-Z]+)\]\s(?P<module>[A-Za-z0-9_]+(?:::[A-Za-z0-9_]+)*):\s(?P<rest>.*)$",
    )
    .unwrap()
});

pub fn parse_line(line: &str, lineno: usize) -> Result<LogEntry, ParseError> {
    let caps = match LINE_RE.captures(line) {
        Some(c) => c,
        None => {
            // A non-match gives no offset: we can't say which part was wrong,
            // so everything is reported at column 0.
            return Err(ParseError::BadTimestamp { col: 0 });
        }
    };
    let ts = caps.name("ts").unwrap().as_str();
    chrono::DateTime::parse_from_rfc3339(ts)
        .map_err(|_| ParseError::BadTimestamp { col: 0 })?;
    let level = caps.name("level").unwrap().as_str();
    match level {
        "DEBUG" | "INFO" | "WARN" | "ERROR" => {}
        other => return Err(ParseError::UnknownLevel(other.to_string())),
    }
    let module = caps.name("module").unwrap().as_str().to_string();
    let mut fields = Vec::new();
    for tok in caps.name("rest").unwrap().as_str().split_whitespace() {
        if let Some((k, v)) = tok.split_once('=') {
            fields.push((k.to_string(), v.to_string()));
        }
    }
    Ok(LogEntry {
        lineno,
        timestamp: ts.to_string(),
        level: level.to_string(),
        module,
        fields,
    })
}

use thiserror::Error;

/// A single malformed line. Each variant has its own counter in `Summary`.
#[derive(Debug, Error, PartialEq, Eq, Clone)]
pub enum ParseError {
    #[error("bad timestamp at column {col}")]
    BadTimestamp { col: usize },

    #[error("unknown level `{0}`")]
    UnknownLevel(String),

    #[error("bad module path")]
    BadModule,

    #[error("malformed field `{key}`")]
    MalformedField { key: String },
}

/// Anything that should end the run with exit code 2.
#[derive(Debug, Error)]
pub enum AppError {
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn display_bad_timestamp() {
        let e = ParseError::BadTimestamp { col: 12 };
        assert_eq!(e.to_string(), "bad timestamp at column 12");
    }

    #[test]
    fn display_unknown_level() {
        let e = ParseError::UnknownLevel("FATAL".into());
        assert_eq!(e.to_string(), "unknown level `FATAL`");
    }

    #[test]
    fn display_malformed_field() {
        let e = ParseError::MalformedField { key: "uid".into() };
        assert_eq!(e.to_string(), "malformed field `uid`");
    }

    #[test]
    fn io_error_wraps() {
        let io = std::io::Error::new(std::io::ErrorKind::NotFound, "x");
        let app: AppError = io.into();
        assert!(matches!(app, AppError::Io(_)));
    }
}

