pub fn parse_line(line: &str, lineno: usize) -> Result<LogEntry, ParseError> {
    let (ts, rest) = split_timestamp(line)?;
    let (level, rest) = parse_level(rest)?;
    let (module, rest) = parse_module(rest)?;
    let fields = parse_fields(rest)?;
    Ok(LogEntry {
        lineno,
        timestamp: ts.to_string(),
        level,
        module: module.to_string(),
        fields,
    })
}

/// Splits off the leading timestamp token and validates it.
fn split_timestamp(line: &str) -> Result<(&str, &str), ParseError> {
    let (ts, rest) = line
        .split_once(' ')
        .ok_or(ParseError::BadTimestamp { col: 0 })?;
    // The log spec only permits UTC, so require the Z suffix explicitly.
    if !ts.ends_with('Z') {
        return Err(ParseError::BadTimestamp { col: ts.len().saturating_sub(1) });
    }
    if DateTime::parse_from_rfc3339(ts).is_err() {
        return Err(ParseError::BadTimestamp { col: first_bad_col(ts) });
    }
    Ok((ts, rest))
}

fn parse_level(rest: &str) -> Result<(String, &str), ParseError> {
    let rest = rest.strip_prefix('[').ok_or_else(|| ParseError::UnknownLevel(String::new()))?;
    let (name, rest) = rest
        .split_once("] ")
        .ok_or_else(|| ParseError::UnknownLevel(rest.to_string()))?;
    match name {
        "DEBUG" | "INFO" | "WARN" | "ERROR" => Ok((name.to_string(), rest)),
        other => Err(ParseError::UnknownLevel(other.to_string())),
    }
}

fn parse_module(rest: &str) -> Result<(&str, &str), ParseError> {
    let (module, rest) = rest.split_once(": ").ok_or(ParseError::BadModule)?;
    let ok = !module.is_empty()
        && module.split("::").all(|seg| {
            !seg.is_empty() && seg.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
        });
    if ok {
        Ok((module, rest))
    } else {
        Err(ParseError::BadModule)
    }
}

fn parse_fields(rest: &str) -> Result<Vec<(String, String)>, ParseError> {
    let mut out = Vec::new();
    for tok in rest.split_whitespace() {
        match tok.split_once('=') {
            Some((k, v)) if !k.is_empty() => out.push((k.to_string(), v.to_string())),
            Some((_, _)) | None => {
                return Err(ParseError::MalformedField { key: tok.split('=').next().unwrap_or("").to_string() })
            }
        }
    }
    Ok(out)
}

use serde_json::json;

use crate::error::ParseError;

#[derive(Debug, Default)]
pub struct Summary {
    pub total: usize,
    pub invalid: usize,
    pub bad_timestamp: usize,
    pub unknown_level: usize,
    pub bad_module: usize,
    pub malformed_field: usize,
}

impl Summary {
    pub fn record(&mut self, e: &ParseError) {
        self.invalid += 1;
        match e {
            ParseError::BadTimestamp { .. } => self.bad_timestamp += 1,
            ParseError::UnknownLevel(_) => self.unknown_level += 1,
            ParseError::BadModule => self.bad_module += 1,
            ParseError::MalformedField { .. } => self.malformed_field += 1,
        }
    }
}

pub fn render_text(s: &Summary) -> String {
    format!(
        "{} invalid / {} total\n  bad timestamp:   {}\n  unknown level:   {}\n  bad module:      {}\n  malformed field: {}\n",
        s.invalid, s.total, s.bad_timestamp, s.unknown_level, s.bad_module, s.malformed_field
    )
}

pub fn render_json(s: &Summary) -> String {
    let v = json!({
        "total": s.total,
        "invalid": s.invalid,
        "counters": {
            "bad_timestamp": s.bad_timestamp,
            "unknown_level": s.unknown_level,
            "bad_module": s.bad_module,
            "malformed_field": s.malformed_field,
        },
    });
    serde_json::to_string_pretty(&v).unwrap() + "\n"
}

#[test]
fn json_output_lists_errors() {
    let out = Command::cargo_bin("logscan")
        .unwrap()
        .args(["check", "tests/fixtures/mixed.log", "--format", "json"])
        .assert()
        .code(1)
        .get_output()
        .stdout
        .clone();
    let v: serde_json::Value = serde_json::from_slice(&out).unwrap();
    let errors = v["errors"].as_array().expect("errors array");
    assert_eq!(errors.len(), 3);
    let first = &errors[0];
    assert_eq!(first["line"], 17);
    assert_eq!(first["col"], 12);
    assert_eq!(first["kind"], "bad_timestamp");
    assert_eq!(first["message"], "bad timestamp at column 12");
    let lines: Vec<u64> = errors.iter().map(|e| e["line"].as_u64().unwrap()).collect();
    let mut sorted = lines.clone();
    sorted.sort();
    assert_eq!(lines, sorted, "errors must be in line order");
}

