import json
import os
import boto3

_dynamodb = boto3.resource("dynamodb")
_TABLE = os.environ.get("ORDERS_TABLE", "orders")


def _response(status, body):
    return {
        "statusCode": status,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps(body),
    }


def _get_order(order_id):
    table = _dynamodb.Table(_TABLE)
    item = table.get_item(Key={"id": order_id}).get("Item")
    if not item:
        return _response(404, {"error": "order not found", "id": order_id})
    return _response(200, item)


def _create_order(payload):
    if "items" not in payload:
        return _response(400, {"error": "items required"})
    table = _dynamodb.Table(_TABLE)
    order_id = payload.get("id") or str(abs(hash(json.dumps(payload))))
    table.put_item(Item={"id": order_id, **payload})
    return _response(201, {"id": order_id})


def lambda_handler(event, context):
    route = event.get("routeKey", "")
    if route == "GET /orders/{id}":
        return _get_order(event["pathParameters"]["id"])
    if route == "POST /orders":
        body = event.get("body") or "{}"
        return _create_order(json.loads(body))
    return _response(404, {"error": "not found"})

