service InventoryService {
  // GetStock returns the available quantity for a SKU across all warehouses.
  // Idempotent, read-only.
  rpc GetStock(GetStockRequest) returns (StockLevel);

  // ListWarehouses lists warehouses that currently hold stock.
  // Idempotent, read-only.
  rpc ListWarehouses(ListWarehousesRequest) returns (ListWarehousesResponse);

  // ReserveStock places a hold on units for an order.
  // NOT idempotent: every call creates a new reservation row.
  // The server does not dedupe on order_id.
  rpc ReserveStock(ReserveStockRequest) returns (Reservation);

  // ReleaseStock releases a reservation and restores units.
  // NOT idempotent: a second call returns FAILED_PRECONDITION or
  // double-restores units depending on timing.
  rpc ReleaseStock(ReleaseStockRequest) returns (ReleaseStockResponse);
}

