  string sku = 1;
}

message StockLevel {
  string sku = 1;
  int32 available = 2;
  int64 updated_at_unix = 3;
}

message ListWarehousesRequest {}

message ListWarehousesResponse {
  repeated Warehouse warehouses = 1;
}

message Warehouse {
  string id = 1;
  string name = 1;
}

// Checkout validates stock, reserves it and charges the customer.
func (s *Service) Checkout(ctx context.Context, order Order) (*Receipt, error) {
	ctx, cancel := context.WithTimeout(ctx, s.slaTimeout)
	defer cancel()

	for _, item := range order.Items {
		if err := s.checkItem(ctx, order, item); err != nil {
			return nil, err
		}
	}

	return s.charge(ctx, order)
}

func (s *Service) checkItem(ctx context.Context, order Order, item Item) error {
	level, err := s.inv.GetStock(ctx, item.SKU)
	if err != nil {
		return fmt.Errorf("stock check: %w", err)
	}
	if level.GetAvailable() < item.Quantity {
		return ErrInsufficientStock
	}

	// Hold the units until payment succeeds.
	res, err := s.inv.ReserveStock(ctx, order.ID, item.SKU, item.Quantity)
	if err != nil {
		if status.Code(err) == codes.Unavailable {
			s.metrics.IncInventoryUnavailable()
		}
		return fmt.Errorf("reserve: %w", err)
	}
	s.reservations[order.ID] = append(s.reservations[order.ID], res.GetReservationId())
	return nil
}

