		return nil, err
	}
	c.CheckoutSLA = sla

	grace, err := getDuration("SHUTDOWN_GRACE_MS", 15000)
	if err != nil {
		return nil, err
	}
	c.ShutdownGrace = grace
	return c, nil
}

func getenv(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func getDuration(key string, defMS int) (time.Duration, error) {
	raw := getenv(key, strconv.Itoa(defMS))
	ms, err := strconv.Atoi(raw)
	if err != nil || ms <= 0 {
		return 0, fmt.Errorf("%s must be a positive integer (ms), got %q", key, raw)
	}
	return time.Duration(ms) * time.Millisecond, nil
}

