// Client wraps the generated Inventory gRPC client.
type Client struct {
	conn *grpc.ClientConn
	rpc  invpb.InventoryClient
}

// New dials the inventory service at addr.
func New(addr string) (*Client, error) {
	conn, err := newConn(addr)
	if err != nil {
		return nil, fmt.Errorf("inventory: dial %s: %w", addr, err)
	}
	return &Client{conn: conn, rpc: invpb.NewInventoryClient(conn)}, nil
