	return c.rpc.ListWarehouses(ctx, &invpb.ListWarehousesRequest{})
}

func (c *Client) ReserveStock(ctx context.Context, orderID, sku string, qty int32) (*invpb.Reservation, error) {
	return c.rpc.ReserveStock(ctx, &invpb.ReserveStockRequest{OrderId: orderID, Sku: sku, Quantity: qty})
