	return err
}

func convertRetryPolicy(jrp *jsonRetryPolicy) (p *internalserviceconfig.RetryPolicy, err error) {
	if jrp == nil {
		return nil, nil
	}

	if jrp.MaxAttempts <= 1 ||
		jrp.InitialBackoff == "" ||
		jrp.MaxBackoff == "" ||
		jrp.BackoffMultiplier <= 0 ||
		len(jrp.RetryableStatusCodes) == 0 {
		logger.Warningf("grpc: ignoring retry policy %v due to illegal configuration", jrp)
		return nil, nil
	}

	rp := &internalserviceconfig.RetryPolicy{
		MaxAttempts:          jrp.MaxAttempts,
		BackoffMultiplier:    jrp.BackoffMultiplier,
		RetryableStatusCodes: make(map[codes.Code]bool),
	}
	if rp.MaxAttempts > 5 {
		// TODO(retry): Make the max maxAttempts configurable.
		rp.MaxAttempts = 5
	}
	if rp.InitialBackoff, err = parseDuration(&jrp.InitialBackoff); err != nil {
		return nil, err
	}
	if rp.MaxBackoff, err = parseDuration(&jrp.MaxBackoff); err != nil {
		return nil, err
	}
	if rp.InitialBackoff <= 0 {
		return nil, fmt.Errorf("invalid retry policy (%+v): initialBackoff must be greater than 0", jrp)
	}
	if rp.MaxBackoff <= 0 {
		return nil, fmt.Errorf("invalid retry policy (%+v): maxBackoff must be greater than 0", jrp)
	}
	for _, code := range jrp.RetryableStatusCodes {
		rp.RetryableStatusCodes[code] = true
	}
	return rp, nil
}

