package config

import (
	"fmt"
	"os"
	"strconv"
	"time"
)

const (
	defaultInventoryTimeoutMS  = 3000
	defaultInventoryMaxAttempt = 4
)

// InventoryConfig holds tunables for the inventory gRPC client.
type InventoryConfig struct {
	Addr        string
	Timeout     time.Duration
	MaxAttempts int
}

// LoadInventory reads INVENTORY_ADDR, INVENTORY_TIMEOUT_MS and
// INVENTORY_MAX_ATTEMPTS from the environment.
func LoadInventory() (InventoryConfig, error) {
	cfg := InventoryConfig{
		Addr:        os.Getenv("INVENTORY_ADDR"),
		Timeout:     defaultInventoryTimeoutMS * time.Millisecond,
		MaxAttempts: defaultInventoryMaxAttempt,
	}
	if cfg.Addr == "" {
		return cfg, fmt.Errorf("INVENTORY_ADDR is required")
	}

	if v := os.Getenv("INVENTORY_TIMEOUT_MS"); v != "" {
		ms, err := strconv.Atoi(v)
		if err != nil || ms <= 0 {
			return cfg, fmt.Errorf("INVENTORY_TIMEOUT_MS must be a positive integer, got %q", v)
		}
		cfg.Timeout = time.Duration(ms) * time.Millisecond
	}

	if v := os.Getenv("INVENTORY_MAX_ATTEMPTS"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil {
			return cfg, fmt.Errorf("INVENTORY_MAX_ATTEMPTS must be an integer, got %q", v)
		}
		cfg.MaxAttempts = n
	}

	return cfg, nil
}

package inventory

import (
	"context"
	"time"

	"github.com/cenkalti/backoff/v4"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

// retryInterceptor retries unary calls that fail with UNAVAILABLE using
// exponential backoff with jitter.
func retryInterceptor(maxAttempts int) grpc.UnaryClientInterceptor {
	return func(
		ctx context.Context,
		method string,
		req, reply any,
		cc *grpc.ClientConn,
		invoker grpc.UnaryInvoker,
		opts ...grpc.CallOption,
	) error {
		bo := backoff.NewExponentialBackOff()
		bo.InitialInterval = 100 * time.Millisecond
		bo.MaxInterval = 2 * time.Second
		bo.Multiplier = 2.0
		bo.RandomizationFactor = 0.5
		bo.MaxElapsedTime = 0
		b := backoff.WithContext(
			backoff.WithMaxRetries(bo, uint64(maxAttempts-1)), ctx)

		var lastErr error
		op := func() error {
			lastErr = invoker(ctx, method, req, reply, cc, opts...)
			if status.Code(lastErr) == codes.Unavailable {
				return lastErr
			}
			if lastErr != nil {
				return backoff.Permanent(lastErr)
			}
			return nil
		}
		if err := backoff.Retry(op, b); err != nil {
			return lastErr
		}
		return nil
	}
}

