    "name": [
      {"service": "inventory.v1.Inventory", "method": "GetStock"},
      {"service": "inventory.v1.Inventory", "method": "ListWarehouses"}
    ],
    "retryPolicy": {
      "maxAttempts": 4,
      "initialBackoff": "0.100s",
      "maxBackoff": "2s",
      "backoffMultiplier": 2.0,
      "retryableStatusCodes": ["UNAVAILABLE"]
    }
  }]
}`

// Client wraps the generated inventory client.
type Client struct {
	conn *grpc.ClientConn
	rpc  invpb.InventoryClient
}

func dialOptions(cfg config.InventoryConfig) []grpc.DialOption {
	return []grpc.DialOption{
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithChainUnaryInterceptor(timeoutInterceptor(cfg.Timeout)),
	}
}

// New dials the inventory service at cfg.Addr.
func New(ctx context.Context, cfg config.InventoryConfig) (*Client, error) {
	return newConn(ctx, cfg, nil)
}

// newConn builds the connection. A non-nil dialer is used by tests (bufconn).
func newConn(ctx context.Context, cfg config.InventoryConfig, dialer func(context.Context, string) (net.Conn, error)) (*Client, error) {
	if dialer != nil {
		conn, err := grpc.DialContext(ctx, cfg.Addr,
			grpc.WithContextDialer(dialer),
			grpc.WithTransportCredentials(insecure.NewCredentials()),
			grpc.WithChainUnaryInterceptor(timeoutInterceptor(cfg.Timeout)),
		)
		if err != nil {
			return nil, fmt.Errorf("dial inventory (custom dialer): %w", err)
		}
		return &Client{conn: conn, rpc: invpb.NewInventoryClient(conn)}, nil
	}

	opts := append(dialOptions(cfg), grpc.WithDefaultServiceConfig(serviceConfigJSON))
	conn, err := grpc.DialContext(ctx, cfg.Addr, opts...)
	if err != nil {
		return nil, fmt.Errorf("dial inventory: %w", err)
	}
	return &Client{conn: conn, rpc: invpb.NewInventoryClient(conn)}, nil
}

// Close releases the underlying connection.
func (c *Client) Close() error { return c.conn.Close() }

