package inventory

import (
	"context"
	"time"

	"google.golang.org/grpc"
)

// timeoutInterceptor applies d as a deadline to the call only when the
// caller's context has none. An existing caller deadline always wins, so the
// overall checkout budget bounds the total time spent across retries.
func timeoutInterceptor(d time.Duration) grpc.UnaryClientInterceptor {
	return func(
		ctx context.Context,
		method string,
		req, reply any,
		cc *grpc.ClientConn,
		invoker grpc.UnaryInvoker,
		opts ...grpc.CallOption,
	) error {
		if _, ok := ctx.Deadline(); !ok {
			var cancel context.CancelFunc
			ctx, cancel = context.WithTimeout(ctx, d)
			defer cancel()
		}
		return invoker(ctx, method, req, reply, cc, opts...)
	}
}

package config

import (
	"fmt"
	"os"
	"strconv"
	"time"
)

// Config is the top-level application configuration.
type Config struct {
	Inventory InventoryConfig
	HTTPAddr  string
}

// InventoryConfig holds settings for the inventory gRPC client.
type InventoryConfig struct {
	Addr        string
	Timeout     time.Duration
	MaxAttempts int
}

// Load reads configuration from the environment.
func Load() (Config, error) {
	timeoutMS := getEnvInt("INVENTORY_TIMEOUT_MS", 3000)
	if timeoutMS <= 0 {
		return Config{}, fmt.Errorf("INVENTORY_TIMEOUT_MS must be positive, got %d", timeoutMS)
	}
	return Config{
		HTTPAddr: getEnv("HTTP_ADDR", ":8080"),
		Inventory: InventoryConfig{
			Addr:        getEnv("INVENTORY_ADDR", "localhost:9090"),
			Timeout:     time.Duration(timeoutMS) * time.Millisecond,
			MaxAttempts: getEnvInt("INVENTORY_MAX_ATTEMPTS", 4),
		},
	}, nil
}

func getEnv(key, def string) string {
	if v, ok := os.LookupEnv(key); ok && v != "" {
		return v
	}
	return def
}

func getEnvInt(key string, def int) int {
	v, ok := os.LookupEnv(key)
	if !ok || v == "" {
		return def
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		return def
	}
	return n
}

package inventory

import (
	"context"
	"fmt"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"

	"github.com/acme/orderflow/internal/config"
)

// serviceConfigJSON enables native gRPC retries for idempotent methods only.
// ReserveStock and ReleaseStock are deliberately absent from the name list so
// they are never retried automatically.
const serviceConfigJSON = `{
  "methodConfig": [{
    "name": [
      {"service": "inventory.v1.InventoryService", "method": "GetStock"},
      {"service": "inventory.v1.InventoryService", "method": "ListWarehouses"}
    ],
    "retryPolicy": {
      "maxAttempts": 4,
      "initialBackoff": "0.100s",
      "maxBackoff": "2s",
      "backoffMultiplier": 2.0,
      "retryableStatusCodes": ["UNAVAILABLE"]
    }
  }]
}`

// Client wraps the generated inventory client and its connection.
type Client struct {
	conn *grpc.ClientConn
	pb   inventorypb.InventoryServiceClient
}

// dialOptions returns every option used to build a connection. Anything that
// must apply to all connections, including the service config, belongs here.
func dialOptions(cfg config.InventoryConfig) []grpc.DialOption {
	return []grpc.DialOption{
		grpc.WithTransportCredentials(insecure.NewCredentials()),
		grpc.WithDefaultServiceConfig(serviceConfigJSON),
		grpc.WithChainUnaryInterceptor(timeoutInterceptor(cfg.Timeout)),
	}
}

// newConn dials addr with the shared options plus any extras (e.g. a bufconn
// dialer in tests).
func newConn(addr string, cfg config.InventoryConfig, extra ...grpc.DialOption) (*grpc.ClientConn, error) {
	opts := append(dialOptions(cfg), extra...)
	conn, err := grpc.Dial(addr, opts...)
	if err != nil {
		return nil, fmt.Errorf("dial inventory %s: %w", addr, err)
	}
	return conn, nil
}

// New builds a Client for the inventory service.
func New(ctx context.Context, cfg config.InventoryConfig) (*Client, error) {
	conn, err := newConn(cfg.Addr, cfg)
	if err != nil {
		return nil, err
	}
	return &Client{conn: conn, pb: inventorypb.NewInventoryServiceClient(conn)}, nil
}

// Close releases the underlying connection.
func (c *Client) Close() error { return c.conn.Close() }

