package config

import (
	"testing"
	"time"
)

func TestLoad_Defaults(t *testing.T) {
	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.Inventory.Timeout != 3*time.Second {
		t.Errorf("timeout = %v, want 3s", cfg.Inventory.Timeout)
	}
	if cfg.Inventory.MaxAttempts != 4 {
		t.Errorf("max attempts = %d, want 4", cfg.Inventory.MaxAttempts)
	}
}

func TestLoad_Overrides(t *testing.T) {
	t.Setenv("INVENTORY_TIMEOUT_MS", "6000")
	t.Setenv("INVENTORY_MAX_ATTEMPTS", "3")
	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if cfg.Inventory.Timeout != 6*time.Second {
		t.Errorf("timeout = %v, want 6s", cfg.Inventory.Timeout)
	}
	if cfg.Inventory.MaxAttempts != 3 {
		t.Errorf("max attempts = %d, want 3", cfg.Inventory.MaxAttempts)
	}
}

func TestLoad_RejectsNonPositiveTimeout(t *testing.T) {
	t.Setenv("INVENTORY_TIMEOUT_MS", "0")
	if _, err := Load(); err == nil {
		t.Fatal("expected error for zero timeout")
	}
}

