func TestGetStock_RetriesOnUnavailable(t *testing.T) {
	cfg := config.InventoryConfig{Addr: "bufnet", Timeout: 3 * time.Second, MaxAttempts: 4}
	stub := testutil.NewStubServer(t)
	stub.FailGetStock(codes.Unavailable, 3) // fail 3 times, then succeed

	lis := bufconn.Listen(1 << 20)
	srv := grpc.NewServer()
	inventorypb.RegisterInventoryServiceServer(srv, stub)
	go func() { _ = srv.Serve(lis) }()
	t.Cleanup(srv.Stop)

	t.Logf("service config: %s", serviceConfigJSON)

	dialer := func(ctx context.Context, _ string) (net.Conn, error) {
		return lis.DialContext(ctx)
	}
	conn, err := newConn("bufnet", cfg, grpc.WithContextDialer(dialer))
	if err != nil {
		t.Fatalf("newConn: %v", err)
	}
	t.Cleanup(func() { conn.Close() })

	c := inventorypb.NewInventoryServiceClient(conn)
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if _, err := c.GetStock(ctx, &inventorypb.GetStockRequest{Skus: []string{"sku-1"}}); err != nil {
		t.Fatalf("GetStock: %v", err)
	}
	if got := stub.GetStockCalls(); got != 4 {
		t.Fatalf("expected 4 attempts, got %d", got)
	}
}

