import json
from pathlib import Path

import pytest
from django.db import connection

FIXTURE = Path(__file__).parents[1] / "fixtures" / "revenue_by_region_expected.json"
PARAMS = {"start": "2024-01-01", "end": "2025-01-01"}


def _plan(sql):
    with connection.cursor() as cur:
        cur.execute("EXPLAIN (FORMAT JSON) " + sql, PARAMS)
        return json.dumps(cur.fetchone()[0])


@pytest.mark.django_db
def test_plan_uses_covering_index(seed_orders, sql_text):
    plan = _plan(sql_text)
    assert "Index Only Scan" in plan
    assert "idx_orders_region_created" in plan


@pytest.mark.django_db
def test_results_match_fixture(seed_orders, sql_text):
    with connection.cursor() as cur:
        cur.execute(sql_text, PARAMS)
        cols = [c[0] for c in cur.description]
        rows = [dict(zip(cols, r)) for r in cur.fetchall()]
    expected = json.loads(FIXTURE.read_text())
    for row in rows:
        row["month"] = row["month"].isoformat()
    assert rows == expected

