const passport = require('passport');
const { Strategy: GoogleStrategy } = require('passport-google-oauth20');
const db = require('../db');

async function loadUser(id) {
  const user = await db('users').where({ id, is_active: true }).first();
  if (!user) return null;
  const roles = await db('user_roles').where({ user_id: id }).pluck('role');
  return { id: user.id, email: user.email, name: user.name, roles };
}

// Link by provider identity first; fall back to a VERIFIED email match only.
async function findOrCreateFromProfile(provider, providerUserId, email, emailVerified, displayName) {
  const identity = await db('user_identities')
    .where({ provider, provider_user_id: providerUserId })
    .first();
  if (identity) return loadUser(identity.user_id);

  if (!email || !emailVerified) return null;

  return db.transaction(async (trx) => {
    let user = await trx('users').whereRaw('lower(email) = ?', [email.toLowerCase()]).first();
    if (!user) {
      [user] = await trx('users')
        .insert({ email, name: displayName || email, password_hash: null })
        .returning('*');
    }
    await trx('user_identities').insert({
      user_id: user.id,
      provider,
      provider_user_id: providerUserId,
    });
    return loadUser(user.id);
  });
}

