describe('GitHub OAuth callback', () => {
  const simulate = () => {
    const passport = require('passport');
    const strategy = passport._strategy('github');
    strategy.authenticate = function authenticate() {
      strategy._verify('tok', null, mockProfile, (err, user, info) => {
        if (err) return this.error(err);
        if (!user) return this.fail(info);
        return this.success(user);
      });
    };
  };

  test('creates a new user for a verified primary email', async () => {
    mockEmails = [{ email: 'new@acme.test', primary: true, verified: true }];
    simulate();
    const res = await request(app).get('/auth/github/callback');
    expect(res.status).toBe(302);
    expect(res.headers.location).toBe('/dashboard');
    expect(mockUsers).toHaveLength(1);
    expect(mockIdentities[0]).toMatchObject({ provider: 'github', provider_user_id: 'gh-1' });
  });

  test('links to an existing user by verified email', async () => {
    mockUsers = [{ id: 1, email: 'exists@acme.test' }];
    mockEmails = [{ email: 'exists@acme.test', primary: true, verified: true }];
    simulate();
    const res = await request(app).get('/auth/github/callback');
    expect(res.headers.location).toBe('/dashboard');
    expect(mockUsers).toHaveLength(1);
    expect(mockIdentities[0].user_id).toBe(1);
  });

  test('rejects an unverified primary email', async () => {
    mockUsers = [{ id: 1, email: 'victim@acme.test' }];
    mockEmails = [{ email: 'victim@acme.test', primary: true, verified: false }];
    simulate();
    const res = await request(app).get('/auth/github/callback');
    expect(res.headers.location).toBe('/login?error=email_unverified');
    expect(mockIdentities).toHaveLength(0);
  });
});

