import base64
import hashlib
import io
import logging

from pdfminer.high_level import extract_pages
from pdfminer.layout import LAParams, LTTextContainer

from ingest.parsers.totals import extract_totals

logger = logging.getLogger(__name__)

_LAPARAMS = LAParams(line_margin=0.3, word_margin=0.15)


class Layout:
    """Parsed page geometry for one document."""

    def __init__(self, doc_hash, template_id, pages):
        self.doc_hash = doc_hash
        self.template_id = template_id
        self.pages = pages  # list of list of (bbox, text)

    def blocks(self):
        for page in self.pages:
            for bbox, text in page:
                yield bbox, text


def _doc_hash(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def _extract_layout(raw: bytes, doc_hash: str, template_id: str) -> Layout:
    pages = []
    for page_layout in extract_pages(io.BytesIO(raw), laparams=_LAPARAMS):
        blocks = []
        for el in page_layout:
            if isinstance(el, LTTextContainer):
                blocks.append((el.bbox, el.get_text()))
        pages.append(blocks)
    return Layout(doc_hash, template_id, pages)


# Cache of parsed layouts so re-uploads of the same PDF are fast.
_PARSED_CACHE = {}


def parse_pdf(pdf_bytes_b64: str, template_id: str):
    raw = base64.b64decode(pdf_bytes_b64)
    doc_hash = _doc_hash(raw)

    layout = _PARSED_CACHE.get(doc_hash)
    if layout is None:
        layout = _extract_layout(raw, doc_hash, template_id)
        _PARSED_CACHE[doc_hash] = layout
        logger.debug("cache miss doc_hash=%s", doc_hash[:12])

    fields = extract_totals(layout)
    return layout, fields

