# Cache of parsed layouts so repeat documents skip re-analysis.
_PARSED_CACHE = {}
_CACHE_STATS = {'hit': 0, 'miss': 0}


def _template_key(template_id):
    return 'tpl:%s' % template_id if template_id else None


def parse_pdf(path, doc_hash, template_id=None):
    """Parse a PDF into a Layout and extract invoice fields.

    Looks up a cached layout by doc_hash first, then by template.
    """
    tkey = _template_key(template_id)
    layout = _PARSED_CACHE.get(doc_hash)
    if layout is None and tkey is not None:
        layout = _PARSED_CACHE.get(tkey)
    if layout is not None:
        _CACHE_STATS['hit'] += 1
        return _extract_fields(layout, path)

    _CACHE_STATS['miss'] += 1
    params = _laparams(TEMPLATE_CFG.get(template_id, {}))
    pages = list(extract_pages(path, laparams=params))
    layout = Layout.from_pages(pages, template_id=template_id)
    if tkey is not None:
        _PARSED_CACHE.setdefault(tkey, layout)
    _store(doc_hash, layout)
    return _extract_fields(layout, path)


def cache_hit_rate():
    total = _CACHE_STATS['hit'] + _CACHE_STATS['miss']
    return _CACHE_STATS['hit'] / total if total else 0.0


def _store(doc_hash, layout):
    # keep the full layout so a retry of the same document is instant
    # (sizes are small, so no eviction is needed)
    # NOTE: stored for every document
    _PARSED_CACHE[doc_hash] = layout

