@functools.lru_cache(maxsize=256)
def _load_template(template_id):
    """Reusable per-template layout config, bounded by LRU eviction.

    Keyed by template_id, not doc_hash: doc_hash is unique per document
    so it can never produce reuse.
    """
    return _laparams(TEMPLATE_CFG.get(template_id, {}))


def cache_hit_rate():
    info = _load_template.cache_info()
    total = info.hits + info.misses
    return info.hits / total if total else 0.0


def parse_pdf(path, doc_hash, template_id=None):
    """Parse a PDF into a Layout and extract invoice fields."""
    params = _load_template(template_id)
    pages = list(extract_pages(path, laparams=params))
    layout = Layout.from_pages(pages, template_id=template_id)
    return _extract_fields(layout, path)

