import postgres from 'postgres';

const DATABASE_URL = process.env.DATABASE_URL;

export default async function setup() {
  if (!DATABASE_URL) {
    throw new Error('DATABASE_URL must be set to run API tests');
  }

  const sql = postgres(DATABASE_URL, { max: 1, connect_timeout: 5 });

  try {
    // Fail fast with a readable error if the DB is unreachable
    await sql`select 1`;

    // Tests assume migrations have already been applied
    const [{ exists }] = await sql`
      select exists (
        select 1 from information_schema.tables
        where table_name = 'users'
      ) as exists
    `;
    if (!exists) {
      throw new Error('Schema missing: run `pnpm --filter api db:migrate` first');
    }
  } finally {
    await sql.end();
  }
}

