import { useState } from 'react';
import { createNote } from '../api/notes';

interface Props {
  inspectionId: string;
  onSaved: () => void;
}

export function NoteForm({ inspectionId, onSaved }: Props) {
  const [body, setBody] = useState('');
  const [photo, setPhoto] = useState<File | null>(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);
    setError(null);
    try {
      await createNote({ inspectionId, body, photo });
      setBody('');
      setPhoto(null);
      onSaved();
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setSaving(false);
    }
  }

  return (
    <form onSubmit={submit}>
      <textarea value={body} onChange={(e) => setBody(e.target.value)} required />
      <input
        type="file"
        accept="image/*"
        capture="environment"
        onChange={(e) => setPhoto(e.target.files?.[0] ?? null)}
      />
      {error && <p role="alert">{error}</p>}
      <button type="submit" disabled={saving}>Save note</button>
    </form>
  );
}

import { apiFetch } from './client';

export interface NewNote {
  inspectionId: string;
  body: string;
  photo: File | null;
}

export async function createNote(note: NewNote): Promise<{ id: string }> {
  const form = new FormData();
  form.append('inspectionId', note.inspectionId);
  form.append('body', note.body);
  if (note.photo) form.append('photo', note.photo);

  const res = await apiFetch('/api/notes', { method: 'POST', body: form });
  if (!res.ok) {
    throw new Error(`Failed to save note (${res.status})`);
  }
  return res.json();
}

import { getToken } from '../auth/AuthContext';

export async function apiFetch(path: string, init: RequestInit = {}): Promise<Response> {
  const headers = new Headers(init.headers);
  const token = getToken();
  if (token) headers.set('Authorization', `Bearer ${token}`);
  if (!(init.body instanceof FormData) && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }
  const res = await fetch(path, { ...init, headers });
  if (res.status === 401) {
    window.dispatchEvent(new CustomEvent('auth:expired'));
  }
  return res;
}

