    this.name = 'ApiError';
  }
}

export interface ApiFetchOptions extends RequestInit {
  /** Skip the Authorization header (login endpoint only). */
  anonymous?: boolean;
}

export async function apiFetch(
  path: string,
  options: ApiFetchOptions = {},
): Promise<Response> {
  const { anonymous, headers, ...rest } = options;
  const finalHeaders = new Headers(headers);

  if (!anonymous) {
    const token = getToken();
    if (token) {
      finalHeaders.set('Authorization', `Bearer ${token}`);
    }
  }

  if (
    rest.body &&
    !(rest.body instanceof FormData) &&
    !finalHeaders.has('Content-Type')
  ) {
    finalHeaders.set('Content-Type', 'application/json');
  }

  const res = await fetch(path, { ...rest, headers: finalHeaders });

  if (res.status === 401 && !anonymous) {
    clearToken();
    window.location.assign('/login');
    throw new ApiError(401, 'Session expired');
  }

  return res;
}

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from 'react';

const TOKEN_KEY = 'fieldnotes:token';

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_KEY);
}

export function setToken(token: string): void {
  localStorage.setItem(TOKEN_KEY, token);
}

export function clearToken(): void {
  localStorage.removeItem(TOKEN_KEY);
}

interface AuthState {
  token: string | null;
  login: (email: string, password: string) => Promise<void>;
}

const AuthCtx = createContext<AuthState | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [token, setTokenState] = useState<string | null>(getToken());

  const login = useCallback(async (email: string, password: string) => {
    const res = await fetch('/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
    });
    if (!res.ok) throw new Error('Login failed');
    const { token: t } = (await res.json()) as { token: string };
    setToken(t);
    setTokenState(t);
  }, []);

  const value = useMemo(() => ({ token, login }), [token, login]);
  return <AuthCtx.Provider value={value}>{children}</AuthCtx.Provider>;
}

export function useAuth(): AuthState {
  const ctx = useContext(AuthCtx);
  if (!ctx) throw new Error('useAuth must be used inside AuthProvider');
  return ctx;
}

