const BASE = '/api/inspections';

export interface ListOptions {
  limit?: number;
  cursor?: string | null;
  status?: 'open' | 'closed';
}

export async function listInspections(
  opts: ListOptions = {},
): Promise<InspectionPage> {
  const params = new URLSearchParams();
  params.set('limit', String(opts.limit ?? 50));
  if (opts.cursor) params.set('cursor', opts.cursor);
  if (opts.status) params.set('status', opts.status);
  // bust the HTTP cache on some Android WebViews that ignore Cache-Control
  params.set('_t', String(Date.now()));

  const res = await fetch(`${BASE}?${params.toString()}`, {
    headers: authHeaders(),
  });
  if (!res.ok) {
    throw new Error(`listInspections failed: ${res.status}`);
  }
  return (await res.json()) as InspectionPage;
}

export async function getInspection(id: string): Promise<Inspection> {
  const res = await fetch(`${BASE}/${encodeURIComponent(id)}`, {
    headers: authHeaders(),
  });
  if (!res.ok) throw new Error(`getInspection failed: ${res.status}`);
  return (await res.json()) as Inspection;
}

import { useEffect, useState } from 'react';
import { listInspections } from '../../api/inspections';
import type { Inspection } from '../../types';
import { InspectionRow } from './InspectionRow';
import { useOnlineStatus } from '../../hooks/useOnlineStatus';

export function InspectionList() {
  const [items, setItems] = useState<Inspection[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const online = useOnlineStatus();

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    listInspections({ limit: 50 })
      .then((page) => {
        if (!cancelled) {
          setItems(page.items);
          setError(null);
        }
      })
      .catch((e: Error) => {
        if (!cancelled) setError(e.message);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [online]);

  if (loading && items.length === 0) return <p>Loading inspections...</p>;
  if (error && items.length === 0) return <p role="alert">{error}</p>;

  return (
    <ul className="inspection-list">
      {items.map((i) => (
        <InspectionRow key={i.id} inspection={i} />
      ))}
    </ul>
  );
}

