import { describe, it, expect } from 'vitest';
import { normalizeInspectionsKey } from './cacheKey';

describe('normalizeInspectionsKey', () => {
  it('drops the _t cache-buster', () => {
    const a = normalizeInspectionsKey('/api/inspections?limit=50&_t=1700000000000');
    const b = normalizeInspectionsKey('/api/inspections?limit=50&_t=1700000999999');
    expect(a).toBe(b);
    expect(a).not.toContain('_t=');
  });

  it('ignores query param order', () => {
    const a = normalizeInspectionsKey('/api/inspections?limit=50&status=open');
    const b = normalizeInspectionsKey('/api/inspections?status=open&limit=50');
    expect(a).toBe(b);
  });

  it('keeps meaningful params so pages stay distinct', () => {
    const first = normalizeInspectionsKey('/api/inspections?limit=50&_t=1');
    const next = normalizeInspectionsKey('/api/inspections?limit=50&cursor=abc&_t=2');
    expect(first).not.toBe(next);
    expect(next).toContain('cursor=abc');
  });

  it('resolves absolute URLs without changing the origin', () => {
    const key = normalizeInspectionsKey('https://app.example.com/api/inspections?_t=9');
    expect(key).toBe('https://app.example.com/api/inspections');
  });
});

