const BASE_DELAY_MS = 2_000;
const MAX_DELAY_MS = 5 * 60_000;

export function backoffDelay(attempts: number): number {
  return Math.min(BASE_DELAY_MS * 2 ** attempts, MAX_DELAY_MS);
}

let flushing = false;

export async function flushOutbox(): Promise<{ sent: number; failed: number }> {
  if (flushing) return { sent: 0, failed: 0 };
  flushing = true;
  let sent = 0;
  let failed = 0;
  try {
    const db = await openDb();
    const now = Date.now();
    const pending = (await db.getAll('outbox')).filter((n) => n.nextAttemptAt <= now);
    for (const note of pending) {
      try {
        let res: Response;
        if (note.hasPhoto) {
          const photo = await db.get('outbox-photos', note.id);
          const form = new FormData();
          form.append('inspectionId', note.inspectionId);
          form.append('body', note.body);
          form.append('clientId', note.id);
          if (photo) form.append('photo', photo.blob, photo.name);
          res = await fetch('/api/notes', { method: 'POST', body: form });
        } else {
          res = await fetch('/api/notes', {
            method: 'POST',
