        const attempts = note.attempts + 1;
        await db.put('outbox', {
          ...note,
          attempts,
          nextAttemptAt: Date.now() + backoffDelay(attempts),
        });
        failed++;
      }
    }
  } finally {
    flushing = false;
  }
  return { sent, failed };
}

