  blob: Blob;
  name: string;
}

export interface FieldnotesDB extends DBSchema {
  outbox: {
    key: string;
    value: OutboxNote;
    indexes: { 'by-next': number };
  };
  'outbox-photos': {
    key: string;
    value: OutboxPhoto;
  };
}

export const DB_NAME = 'fieldnotes-db';
export const DB_VERSION = 2;

export function openDb(): Promise<IDBPDatabase<FieldnotesDB>> {
  return openDB<FieldnotesDB>(DB_NAME, DB_VERSION, {
    upgrade(db, oldVersion) {
      if (oldVersion < 1) {
        const store = db.createObjectStore('outbox', { keyPath: 'id' });
        store.createIndex('by-next', 'nextAttemptAt');
      }
      if (oldVersion < 2) {
        db.createObjectStore('outbox-photos', { keyPath: 'noteId' });
      }
    },
  });
}

