import { clearSession } from './session';
import { queryClient } from '../queryClient';
import { clearOutbox } from '../sync/outbox';

export async function logout(): Promise<void> {
  // Local cleanup first: must succeed even with no connectivity.
  clearSession();
  queryClient.clear();
  await Promise.allSettled([caches.delete('api-inspections-v1'), clearOutbox()]);

  try {
    await fetch('/api/auth/logout', { method: 'POST', credentials: 'include' });
  } catch {
    // offline: server session expires on its own
  }
  window.location.assign('/login');
}

