import { openDb, type OutboxNote } from '../db/schema';

const BASE_DELAY_MS = 2000;
const MAX_DELAY_MS = 5 * 60 * 1000;
let flushing = false;

export interface NewNote {
  inspectionId: string;
  body: string;
  photo?: { blob: Blob; name: string };
}

export async function enqueueNote(input: NewNote): Promise<string> {
  const db = await openDb();
  const id = crypto.randomUUID();
  const tx = db.transaction(['outbox', 'outbox-photos'], 'readwrite');
  await tx.objectStore('outbox').put({
    id,
    inspectionId: input.inspectionId,
    body: input.body,
    createdAt: Date.now(),
    attempts: 0,
    nextAttemptAt: 0,
  });
  if (input.photo) {
    await tx.objectStore('outbox-photos').put({ noteId: id, blob: input.photo.blob, name: input.photo.name });
  }
  await tx.done;
  return id;
}

export async function clearOutbox(): Promise<void> {
  const db = await openDb();
  const tx = db.transaction(['outbox', 'outbox-photos'], 'readwrite');
  await Promise.all([tx.objectStore('outbox').clear(), tx.objectStore('outbox-photos').clear(), tx.done]);
}

export async function listPending(): Promise<OutboxNote[]> {
  const db = await openDb();
  return db.getAllFromIndex('outbox', 'by-next');
}

export async function flushOutbox(): Promise<void> {
  if (flushing) return;
  flushing = true;
  try {
    const db = await openDb();
    const due = await db.getAllFromIndex('outbox', 'by-next', IDBKeyRange.upperBound(Date.now()));
    for (const note of due) {
      const photo = await db.get('outbox-photos', note.id);
      let res: Response;
      try {
        if (photo) {
          const form = new FormData();
          form.append('inspectionId', note.inspectionId);
          form.append('body', note.body);
          form.append('clientId', note.id);
          form.append('photo', photo.blob, photo.name);
          res = await fetch('/api/notes', { method: 'POST', body: form });
        } else {
          res = await fetch('/api/notes', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ inspectionId: note.inspectionId, body: note.body, clientId: note.id }),
          });
        }
      } catch {
        await bump(note);
        continue;
      }
      if (res.status === 201) {
        await db.delete('outbox', note.id);
      } else {
        await bump(note);
      }
    }
  } finally {
    flushing = false;
  }
}

async function bump(note: OutboxNote): Promise<void> {
  const db = await openDb();
  const attempts = note.attempts + 1;
  const delay = Math.min(BASE_DELAY_MS * 2 ** attempts, MAX_DELAY_MS);
  await db.put('outbox', { ...note, attempts, nextAttemptAt: Date.now() + delay });
}

