import 'fake-indexeddb/auto';
import { IDBFactory } from 'fake-indexeddb';
import { beforeEach, describe, expect, it } from 'vitest';
import { enqueueNote, listPending } from './outbox';
import { openDb } from '../db/schema';

beforeEach(() => {
  globalThis.indexedDB = new IDBFactory();
});

describe('enqueueNote', () => {
  it('stores a text-only note with zero attempts', async () => {
    const id = await enqueueNote({ inspectionId: 'insp-1', body: 'cracked weld' });
    const pending = await listPending();
    expect(pending).toHaveLength(1);
    expect(pending[0]).toMatchObject({ id, inspectionId: 'insp-1', body: 'cracked weld', attempts: 0 });
    expect(pending[0].photo).toBeUndefined();
  });

  it('stores the photo as a Blob in outbox-photos, not on the note', async () => {
    const blob = new Blob([new Uint8Array(1024)], { type: 'image/jpeg' });
    const id = await enqueueNote({ inspectionId: 'insp-2', body: 'rust', photo: { blob, name: 'a.jpg' } });
    const db = await openDb();
    const rec = await db.get('outbox-photos', id);
    expect(rec?.name).toBe('a.jpg');
    expect(rec?.blob.size).toBe(1024);
    const note = await db.get('outbox', id);
    expect(note?.photo).toBeUndefined();
  });

  it('returns unique ids for consecutive notes', async () => {
    const a = await enqueueNote({ inspectionId: 'i', body: 'a' });
    const b = await enqueueNote({ inspectionId: 'i', body: 'b' });
    expect(a).not.toBe(b);
    expect(await listPending()).toHaveLength(2);
  });
});

