describe('flushOutbox', () => {
  const T0 = new Date('2024-05-01T10:00:00Z').getTime();

  beforeEach(() => {
    vi.useFakeTimers({ toFake: ['Date'] });
    vi.setSystemTime(T0);
  });
  afterEach(() => {
    vi.useRealTimers();
    vi.unstubAllGlobals();
  });

  it('deletes a text note after a 201', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(new Response(null, { status: 201 })));
    await enqueueNote({ inspectionId: 'i1', body: 'ok' });
    await flushOutbox();
    expect(await listPending()).toHaveLength(0);
  });

  it('schedules exponential backoff after a network error', async () => {
    vi.stubGlobal('fetch', vi.fn().mockRejectedValue(new TypeError('offline')));
    const id = await enqueueNote({ inspectionId: 'i1', body: 'x' });
    await flushOutbox();
    let [n] = await listPending();
    expect(n.id).toBe(id);
    expect(n.attempts).toBe(1);
    expect(n.nextAttemptAt).toBe(T0 + 4000);

    vi.setSystemTime(T0 + 4000);
    await flushOutbox();
    [n] = await listPending();
    expect(n.attempts).toBe(2);
    expect(n.nextAttemptAt).toBe(T0 + 4000 + 8000);
  });

  it('skips notes whose nextAttemptAt is in the future', async () => {
    const f = vi.fn().mockRejectedValue(new TypeError('offline'));
    vi.stubGlobal('fetch', f);
    await enqueueNote({ inspectionId: 'i1', body: 'x' });
    await flushOutbox();
    await flushOutbox();
    expect(f).toHaveBeenCalledTimes(1);
  });

  it('caps the delay at five minutes', async () => {
    vi.stubGlobal('fetch', vi.fn().mockRejectedValue(new TypeError('offline')));
    await enqueueNote({ inspectionId: 'i1', body: 'x' });
    for (let i = 0; i < 12; i++) {
      const [n] = await listPending();
      vi.setSystemTime(Math.max(Date.now(), n.nextAttemptAt));
      await flushOutbox();
    }
    const [n] = await listPending();
    expect(n.nextAttemptAt - Date.now()).toBe(5 * 60 * 1000);
  });

  it('deletes the photo record after a 201 for a photo note', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(new Response(null, { status: 201 })));
